import { d } from './full-schema.mjs';
export const contemporaryDossiers = {
  'poverty-alleviation': [
    d('长期减贫与集中攻坚的区别', 'Long-run reduction and the targeted campaign',
      '改革以来农业生产率、工业就业、城市化和基础设施共同推动大规模减贫，2010年代精准扶贫是长期进程中的一个阶段。世界银行与国务院发展研究中心报告将约八亿人的减贫置于四十余年的增长、农业转型和政策变化中。\n\n贫困减少来自家庭劳动、教育、迁移、市场机会和公共投入，多种机制相互配合。政治动员对资源集中有作用，也要审视谁被识别、服务是否持续及地方如何执行。宏观成就可以明确承认，具体项目仍需逐项评估，二者不构成相互排斥的叙述。',
      'Agricultural productivity, jobs, urbanization and infrastructure drove long-run reduction. Targeted poverty alleviation was a later phase. The roughly 800 million figure in the 2022 report describes four decades of change using its historical international poverty line.\n\nHousehold work, markets and public investment interacted. Aggregate achievement and project-level scrutiny are compatible.', ['poverty-report']),
    d('建档立卡与识别误差', 'Registration and identification errors',
      '精准识别试图把支持落实到具体家庭，收入、住房、教育和健康情况进入登记。家庭收入不稳定、外出劳动难统计和地方关系可能产生漏识别或错误纳入。被登记不是贫困全部现实的完美镜像，未被登记也不证明生活没有困难。\n\n干部考核推动核查与资源下沉，也可能诱发材料负担、过度证明和数字压力。应评价独立抽查、申诉、动态调整和退出后跟踪，而不只看完成率。家庭对就业、土地、迁移和照护的选择，决定项目怎样进入真实生活。',
      'Household registers sought precise targeting but volatile income, migration and local relationships could generate exclusion or inclusion errors. Registration was not a perfect map of need.\n\nPerformance pressure encouraged effort and paperwork risks. Appeals, independent checks and follow-up matter alongside completion rates and beneficiaries’ own choices.', ['poverty-report']),
    d('产业、就业与易地搬迁', 'Industry support, employment and relocation',
      '产业扶持、就业培训和搬迁试图改变长期机会，项目是否成功取决于市场、交通、技能和经营管理。企业补助与培训带来机会，市场、技能和后续支持决定能否转为持续收入。经营成本、债务与市场风险影响家庭净收入，项目规模和个人收益之间存在明显差距。\n\n搬迁可能改善住房、学校与医疗可达性，同时使居民离开土地、亲属和熟悉的生计。自愿程度、后续工作、养老和社区关系决定长期福利。搬迁改善住房后，老人、残障者和照护家庭仍需要就业、医疗及熟人网络支持。',
      'Industry, training and relocation depended on markets, access and management. Business revenue and training attendance did not establish household net income or durable jobs.\n\nNew housing could improve services while disrupting land-based livelihoods and networks. Consent, employment and care determine long-term welfare beyond construction.', ['poverty-report']),
    d('健康、教育与避免返贫', 'Health, education and preventing renewed poverty',
      '疾病、失业和照护负担可能使刚越过收入线的家庭再次困难，减贫因此需要医保、教育与社会救助衔接。参保后的费用与学校质量因地区而异，公共服务的实际水平影响家庭能否维持改善。家庭支付、交通与陪护时间都影响服务实际取得。\n\n儿童教育通过后续升学、职业和家庭生活产生长期影响。残障和慢性病家庭依赖持续照护与社会保障，劳动收入难以独立承担全部生活风险。防返贫监测应注意隐私和申诉，避免为证明达标而压制困难反馈。',
      'Illness, unemployment and care can push households back into hardship. Insurance enrollment and school access do not guarantee affordability or quality.\n\nEducation yields long-term effects; disabled and chronically ill households need sustained support. Monitoring and support affected whether vulnerable households could disclose difficulty and retain assistance.', ['poverty-report', 'universal-health-2013', 'health-reform-2016']),
    d('贫困线与2020年宣告的含义', 'Poverty lines and the 2020 achievement claim',
      '中国宣布完成现行标准下农村绝对贫困消除目标，需保留农村、现行标准与政策验收的范围。农村绝对贫困目标完成后，城市低收入、相对贫困与疾病和就业风险仍持续影响居民。国际购买力平价贫困线定期更新，历次报告按各自标准保存了减贫幅度和仍有困难的人口。\n\n住房、健康、尊严与生活安全共同决定家庭处境，收入线只记录其中的货币维度。肯定绝对贫困大幅下降，与指出新标准和更广福利需求，可以在同一严谨口径下成立。',
      'The announced elimination concerned rural absolute poverty under the applicable national standard. It did not end urban need, relative poverty or vulnerability. International PPP lines also change.\n\nIncome thresholds aid measurement without fully describing health, housing or security. Dates, coverage and multidimensional indicators allow achievement and remaining needs to be assessed together.', ['poverty-report', 'nbs-2025']),
    d('乡村振兴与下一阶段', 'Rural revitalization and the next stage',
      '攻坚后转向乡村振兴和持续支持，农业、公共服务与城乡流动成为长期议题。年轻劳动力外出可以增加收入，也使地方照护、教育和产业面临结构变化。留村者继续依靠土地、亲属与文化联系生活，城乡迁移的政策也影响他们保留或改变生计的选择。\n\n2026年经济再平衡讨论更强调消费与社会保护，减贫经验需要放到新的增长条件中。以往有效的投资方式未必在每个地方继续有效，资源约束要求评估持续性。本书将已实现变化与未来目标分别记录，不把政策规划写成已经完成的社会结果。',
      'Rural revitalization connects agriculture, services and mobility. Migration improves income while changing local care and education; residents’ land and cultural choices matter.\n\nRebalancing in 2026 places welfare and consumption in a new setting. Past investment tools require reassessment. Completed outcomes remain distinct from future plans.', ['poverty-report', 'wb-2026']),
  ],
  'xinjiang-rights': [
    d('安全背景与不可集体归责', 'Security context without collective blame',
      '新疆有多民族、宗教和跨境联系的复杂历史，暴力袭击造成平民伤亡，政府有保护公众的责任。暴力袭击造成真实受害，反恐治理随后扩大到族群、宗教和日常生活，普通居民承受广泛干预。群体身份进入安全归类，使个人在缺少具体犯罪指控的情况下遭到限制。\n\n交通、就业与地区建设同拘禁及宗教限制并行，居民的经济和权利处境受到不同政策影响。把经济成果与权利伤害并列说明，不是以收益抵销伤害。民族、性别、代际和城乡差异使新疆居民形成多种经历。',
      'Violent attacks caused civilian harm and create a duty to protect, but ethnicity and religious practice do not establish individual guilt. Security requires evidence.\n\nDevelopment and rights need separate assessment: economic gains do not resolve arbitrary detention claims. Residents’ experiences vary across communities and social positions.', ['xinjiang-ohchr', 'xinjiang-response']),
    d('2017年前后拘禁体系的扩大', 'Expansion of detention around 2017',
      '2017年前后以反恐和去极端化为名的拘禁及职业教育培训体系明显扩大，人员进入和离开的自愿性、法律依据与期限成为核心问题。政府称其提供技能和预防极端主义，联合国评估及相关证言则指出广泛任意拘禁和严厉限制。人员能否离开、是否受威胁及有无程序保障，揭示设施内的实际强制。\n\n封闭管理限制人员离开与联系家庭，律师、司法复核和明确拘留理由的缺乏加重不安全感。访谈和政策材料呈现严重强制模式，设施与政策调整以后，家庭失联和后续生活仍难以持续追踪。',
      'Around 2017, detention and vocational-training systems expanded. Voluntariness, legal grounds and duration are central. Government training claims contrast with documented arbitrary detention; labels do not determine custody conditions.\n\nFreedom to leave, counsel, review and individualized grounds matter. Evidence gaps and facility variation coexist with established serious patterns.', ['xinjiang-ohchr', 'xinjiang-response']),
    d('2022年联合国评估怎样形成', 'How the 2022 UN assessment was framed',
      '联合国人权高专办2022年评估结合访谈、法律政策、公开文件及政府回应，判断新疆发生严重人权侵犯，任意和歧视性拘禁程度可能构成国际罪行，特别是危害人类罪。这里的“可能构成”是法律评估表述，并非国际法院已经审结并判定每个具体人的刑事责任。\n\n访谈样本、取得材料和现场访问存在限制，报告自身说明证据和方法。法规、机构与见证在报告中相互印证，信息限制仍使完整调查和公开问责受到阻碍。联合国评估依据访谈和政策材料指出严重侵害，报告所述地区与时段界定其调查范围。',
      'OHCHR’s 2022 assessment used interviews, policy and documents with government responses. It found serious violations and said arbitrary, discriminatory detention may constitute international crimes, particularly crimes against humanity. This was not a final criminal judgment against individuals.\n\nMethod and access limits require attention without equating supported findings with unsupported propaganda.', ['xinjiang-ohchr']),
    d('政府回应及如何评价回应', 'The government response and its assessment',
      '中国政府否认评估的主要结论，强调反恐、去极端化、职业培训和发展成就，并质疑材料来源与政治动机。回应全文由联合国网站同时提供，读者应能直接查看。准确陈述政府立场是叙述完整性的要求，不代表它自动推翻独立证据。\n\n评价回应需要逐项核对法律、设施、个人经历和统计，而非只按双方机构身份选择信任。酷刑、任意拘禁和歧视伤害个人安全，相关指控与国家否认构成持续的国际争议。不同结论的支持强弱应清楚呈现，不作机械的五五分配。',
      'China rejected major findings, stressing security, training and development and disputing evidence and motives. The UN-hosted response allows direct reading. Government accounts presented their own defense of the policies.\n\nClaims need point-by-point assessment. Improved security would not legalize torture or arbitrary detention, and grave allegations still require evidence. Neutrality is not equal weight for unequally supported claims.', ['xinjiang-response', 'xinjiang-ohchr']),
    d('宗教、家庭与劳动问题', 'Religion, families and labor',
      '拘禁以外，宗教实践、文化与语言、家庭分离、隐私和劳动安排也进入评估。亲属长期失联使家庭难以得知下落、自由状态与救济渠道，设施调整以后忧虑仍在延续。家庭照护与儿童生活是权利影响的重要部分。\n\n拒绝工作的能力、威胁、工资与行动自由，共同揭示劳动安排中的强制程度。统计和供应链调查具有范围限制，具体产品与地区应分开。本书不把未核实总人数或产业比例作精确图表，而以证据类型和制度问题呈现。',
      'The assessment also concerns religion, culture, family separation, privacy and labor. Closure or graduation claims do not alone resolve relatives’ whereabouts and liberty.\n\nConsent in labor requires the ability to refuse without threat, alongside pay and movement. Contracts or wages alone do not establish voluntariness. Documents, testimony and labor arrangements tied products to specific production conditions and rights concerns.', ['xinjiang-ohchr', 'xinjiang-response']),
    d('2026年前的研究边界', 'Research boundaries through the cutoff',
      '政策和设施随时间变化，2017年以来留下的不同记录展示治理方式的调整与长期后果。调查进入和自由访谈受限，使失联、拘禁后生活与家庭损失的追踪持续困难。应持续区分过去拘禁、目前刑事羁押、就业与监控等不同状态。\n\n国际制裁、供应链规则和外交争论使材料环境更政治化，受害者声音尤其容易被国家竞争遮蔽。本书截至资料截止日不宣称掌握全部实时状况，也不因更新困难删去已经有充分依据的重要事件。',
      'Policies and facilities changed over time, leaving different records of detention and its aftermath. Restricted access complicates tracking, while elapsed time does not remove accountability. Detention, imprisonment, employment and surveillance are distinct statuses.\n\nInternational disputes can obscure affected people. This account protects privacy and distinguishes established past findings from unavailable real-time knowledge.', ['xinjiang-ohchr', 'xinjiang-response']),
  ],
  'leadership-2012': [
    d('领导交接与权力重组', 'Succession and concentration of authority',
      '2012年中共十八大后习近平任总书记，随后出任国家主席，党、国家和军队职位相互结合。此前形成的任期与接班惯例提供背景，但非所有惯例都等于明确法律。新时期中央协调机构、党内纪律和人事安排加强集中统一，政策执行和信息反馈方式随之改变。\n\n权力集中可能加快跨部门行动，也减少不同意见公开表达和制度制衡空间。决策速度、纠错与责任的关系在不同政策中表现各异。普通干部、企业和公民对政策预期的变化，是领导体制如何进入社会的重要路径。',
      'Xi became party general secretary in 2012 and later state president, combining party, state and military authority. Formal law and succession conventions were not identical.\n\nConcentration could improve coordination while narrowing dissent and checks. Decision speed, correction and accountability require evidence beyond leadership style.', ['constitution', 'amendment-2018']),
    d('反腐的治理与政治作用', 'Governance and political roles of anticorruption',
      '反腐回应公众对贪污、特权和权力交易的不满，处理高层与基层官员，改变干部行为和利益网络。查处真实腐败具有公共价值，反腐同时也重组政治联盟与组织控制。反腐打击真实贪腐，也重塑权力关系，调查程序和政治选择性引起争论。\n\n纪律调查与司法审判有不同权限和证据要求，后续监察体制扩大覆盖范围。调查对象的辩护、羁押和复核是评价的重要内容。以运动压力减少某些交易，不必然建立长期透明、利益申报和独立监督；效果需看制度能否持续约束所有掌权者。',
      'Anticorruption addressed real public concerns and changed political networks. Governance value and political consolidation can coexist; neither makes all cases false or every procedure acceptable.\n\nDiscipline, supervision and criminal trial have differing authority. Durable transparency and review matter beyond campaign intensity.', ['constitution', 'amendment-2018', 'political-violence']),
    d('2018年修宪的准确范围', 'The precise scope of the 2018 amendment',
      '2018年修宪取消国家主席、副主席连续任职不得超过两届的规定，并将相关政治思想及监察委员会等内容纳入宪法。2018年删除国家主席、副主席连续任职两届的限制，总书记职务此前已有不同党内规则。实际最高权力来自多个职位和党内结构，文本与政治惯例共同影响接班。\n\n支持者强调连续领导和治理协调，批评者担心权力集中、纠错及接续的不确定性。修宪通过正式程序以后，公众讨论空间和实际约束继续成为制度变化的核心争议。',
      'The 2018 amendment removed the explicit two-consecutive-term limit for state president and vice president and added supervisory institutions and political language. The party general secretary had no identical constitutional clause.\n\nArguments for continuity and concerns about concentration need institutional assessment. Formal passage and freedom to debate are separate questions.', ['amendment-2018', 'constitution']),
    d('党政、市场与社会组织', 'Party, state, markets and civic organizations',
      '党的领导在国家机关、企业和社会组织中获得更突出制度表达，安全与发展目标更加紧密结合。市场交换持续运行，国家产业、监管与党组织权力又增强，两种力量共同塑造经济。\n\n企业面对创新机会与政策边界，社会团体和公民表达面对更强管理。监管可以处理垄断、金融和数据风险，其程序、可预测性及对异议的限制也需分别评价。政策行动改变行政与社会预期，个人保护、反馈渠道和规则稳定性影响其长期成效。',
      'Party leadership gained stronger institutional expression across government, business and civic life. Markets persisted alongside industrial policy and security priorities.\n\nRegulation can address genuine risks while requiring predictable procedures and protected feedback. Announced activity alone does not establish public benefit.', ['constitution', 'amendment-2018', 'ai-rules', 'wb-2026']),
    d('政策动员与社会承受能力', 'Mobilization and social capacity to bear policy',
      '脱贫、环境治理和疫情应对显示集中动员可以迅速投入资源，也可能带来层层加码、指标替代目标和基层避责。地方并非完全被动，仍会解释中央信号并在考核中选择策略。必须追踪具体领域，而非认定集中就必然成功或必然失败。\n\n家庭和企业承担政策调整成本，若缺少申诉与纠错，短期措施可能持续过久。公共参与和真实信息是治理资源，而不仅是需要控制的风险。对某项政策后来的修正，应同时承认改变与分析为何此前难以反馈，避免把所有后果归给少数执行者。',
      'Poverty, environmental and pandemic campaigns showed rapid resource mobilization alongside target distortion and local overimplementation. Local discretion remained consequential.\n\nHouseholds bear adjustment costs. Restricted feedback and appeals made correction harder, while policy reversal later exposed earlier failures.', ['poverty-report', 'climate-ndc', 'who-timeline', 'constitution']),
    d('延续到2026年的观察方法', 'Observing developments through 2026',
      '当代领导史容易被宣传成就或即时政治反应主导，本书以已发生的任职、修法、政策与可核查影响为基础。公开讲话是立场证据，不等同于政策实现或真实私人意图。\n\n增长、国家能力、权利和社会信任不是可以合成一个分数的指标。2026年的经济与社会发展仍在进行，现有正式统计和已发生政策构成当代章节的记录。资料截止日以后事项留待增补，当前叙述保留已知事实和不确定边界，让读者能够检验而不是只能接受结论。',
      'Appointments, laws and announced policies describe the expansion of contemporary leadership authority. Speeches set out public positions; undisclosed internal discussions leave parts of decision-making uncertain.\n\nGrowth, rights and public trust changed through different institutional processes. Incomplete 2026 data and future personnel decisions are not presented as settled history.', ['constitution', 'amendment-2018', 'wb-2026', 'nbs-2025']),
  ],
  'belt-and-road': [
    d('2013年倡议与多样化项目', 'The 2013 initiative and diverse projects',
      '2013年提出丝绸之路经济带与海上丝绸之路，随后成为覆盖基础设施、贸易和融资合作的广泛倡议。铁路、港口、电力与通信项目采用不同合同和融资，中央、企业与伙伴国各有具体决策。部分项目此前已经酝酿，后来纳入倡议。\n\n中国政府、政策银行、商业银行、国企和私人企业角色不同，东道国政府也主动提出建设需求。伙伴国的地方政治、商业利益和战略选择影响合作，项目在多方交涉中形成。立项、招标、融资和运营连续改变成本与收益，也使责任分布于不同机构。',
      'The 2013 land and maritime initiatives grew into a broad framework for infrastructure and finance. Projects differed in contracts, funding and prior origins.\n\nChinese institutions and host governments had distinct roles. Host states also initiated demand; project histories require tracing approval, procurement, finance and operation.', ['bri-economics']),
    d('运输成本与条件性收益', 'Transport costs and conditional gains',
      '交通改善可能缩短运输时间、连接内陆和扩大市场，但世界银行2019年报告中的潜在收益来自情景模型，依赖贸易便利化、竞争和政策配套。模型中的收入和贸易变化随假设与国家条件变化，反映预期潜力。\n\n一条铁路是否有用取决于货源、票价、维护、边境手续和与其他交通方式的连接。线路建设改善通达，需求、价格和运营决定它能带来多少实际收入和公共便利。模型提出潜在收益与风险，运行后的企业和居民经历则反映项目的具体后果。',
      'Transport can reduce time and connect markets, but the World Bank’s 2019 scenarios describe conditional potential, not realized totals.\n\nDemand, pricing, maintenance, border procedures and network links determine value. Mileage records the expansion of construction; fares, access and use shape its social benefits. Operating experience reveals how routes affect travel, freight and regional economies.', ['bri-economics']),
    d('债务、合同与东道国选择', 'Debt, contracts and host-country choices',
      '贷款支持长期项目，也可能在收入不足、汇率变化或财政恶化时增加偿付压力。债权人结构、现金流与公共预算共同决定债务风险，借贷双方的尽调及谈判影响最终负担。\n\n合同透明度、担保、重新谈判和资产安排决定风险分担。所谓债务陷阱的笼统标签与完全互利的宣传都不足以解释每个案例。应检验当时信息、可行替代和后来结果，区分设计不足、商业失败、政治腐败及外部冲击。',
      'Loans can fund development and create repayment stress through weak revenue, currency or fiscal shocks. Sustainability includes all creditors and budgets; host approval does not remove lender diligence.\n\nTransparency, guarantees and renegotiation shape risk. Neither a universal debt-trap label nor universal mutual benefit explains every case.', ['bri-economics', 'wb-2026']),
    d('劳动、土地与环境', 'Labor, land and environment',
      '工程带来就业、道路与电力，也可能涉及征地、迁移、生态破坏和劳动条件争议。工资、技能、安全与当地采购影响劳动收益，工人的来源与合同共同塑造分配。受益的城市企业与失去土地的农村家庭可能不是同一群人。\n\n环境评估、公众咨询与申诉影响居民是否能在项目推进以前参与决定。跨国承包增加责任追踪难度，资金方、承包方和东道国政府各有义务。保护弱势居民不是合作的附属装饰，而是长期运营和社会信任的基础。',
      'Projects can create jobs and services while causing land loss, ecological harm and labor disputes. Worker nationality alone does not measure wages, skills or local procurement.\n\nConsultation, assessment and remedies matter before construction. Financiers, contractors and host authorities retain distinct duties across borders.', ['bri-economics']),
    d('战略影响与第三方竞争', 'Strategic influence and third-party competition',
      '港口、交通和技术标准可能增加中国经济与外交影响，也引发其他国家对安全和依赖的担忧。商业港口、所有权与实际军事使用具有不同安排，具体控制和行动决定其战略作用。每项判断需要地点、控制权、使用协议和实际行为依据。\n\n美国、欧洲、日本等提出不同合作方案，参与国可能利用竞争争取条件，而非只能选择一方。交通改善和发展收益同地缘竞争、权力差距及借贷风险交织。长期结果取决于合同、治理和当地政治。',
      'Infrastructure and standards can increase influence and security concerns. Ownership, control and actual military use determine the strategic roles of commercial facilities.\n\nHost states may negotiate among competing partners. Development and geopolitical competition coexist, with outcomes dependent on governance and contracts.', ['bri-economics']),
    d('从规模扩张到可持续性', 'From expansion to sustainability',
      '后续合作更加关注项目质量、风险和绿色发展，债务调整及全球经济变化影响新项目节奏。政策口号转向不说明所有旧风险已经解决，项目取消也不证明整体倡议没有价值。应逐项观察完成、运营、重谈和失败，不把签约金额当成实际投资。\n\n截至资料截止日，一带一路仍是持续过程，没有统一最终成绩单。公开数据库的项目范围和纳入规则不同，比较需保留年份与方法。本书以可核查机制和条件解释为主，未来补充个案时将同时呈现当地受益、反对意见及合同证据，避免只从出资国视角叙事。',
      'Later emphasis on quality and greener projects operated amid debt adjustment and global change. Announcements, commitments and actual investment differ; individual failures do not settle the entire initiative.\n\nThe process remains ongoing. Databases use differing coverage, so future cases require local perspectives and contract evidence alongside financier narratives.', ['bri-economics', 'wb-2026', 'climate-ndc']),
  ],
  'digital-society': [
    d('从联网到平台基础设施', 'From connectivity to platform infrastructure',
      '互联网、移动通信、电子商务和数字支付改变信息、购物与劳动组织，平台逐渐成为生活基础设施。变化来自网络建设、企业创新、用户采用和国家政策共同作用，不是技术自动决定社会。城乡、年龄和收入差异决定谁容易接入，数字便利也可能使不会使用者更难取得服务。\n\n平台连接商家、消费者、司机和骑手，网络效应使规模优势持续扩大。低价与方便可能伴随劳动强度、商家依赖和市场集中，消费者收益与劳动者处境需要一起观察。数字交易扩大经济活动，平台权力、劳动关系与数据收集同时深入个人生活。',
      'Connectivity, commerce and payments became infrastructure through networks, firms, users and policy. Access differed by age, income and residence.\n\nNetwork effects increased concentration. Convenience coexisted with worker pressure and merchant dependence; transaction volume does not measure fairness or privacy.', ['nbs-2025', 'wechat-research', 'reform-development']),
    d('数据收集与商业权力', 'Data collection and commercial power',
      '搜索、推荐、定位和信用服务依赖数据，用户往往难以了解收集范围、保存时间和跨机构使用。点击同意不必然体现充分理解，尤其在服务不可替代或条款复杂时。企业提高效率与用户数据控制之间存在需要制度解决的张力。\n\n个人信息、公共安全和商业竞争有不同规则目标，监管既可限制滥用，也可能扩大国家取得数据的能力。收集范围、透明度、删除更正与救济渠道影响个人对数据的实际控制。国家与企业分别掌握数据和管理权，个人在两类权力之间面对隐私与申诉困难。',
      'Search, recommendation and location services depend on data that users may poorly understand. Formal consent is weaker where alternatives are unavailable.\n\nCommercial regulation may also expand state access. Data ownership, correction and remedies affect privacy as firms and the state acquire greater information power.', ['wechat-research', 'constitution', 'ai-rules']),
    d('审查的实验性证据', 'Experimental evidence of censorship',
      '多伦多大学Citizen Lab通过技术实验研究微信等平台的内容控制，发现境外注册账号之间传送的某些文件也会被用于建立针对中国注册账号的审查机制。研究通过设计比较推断系统行为，比只凭一条消息发不出更有解释力。\n\n研究在特定账号与材料上发现识别、监测和过滤的联系，平台信息控制由此有了具体技术记录。审查、监测、删除和账户处罚是不同过程，应准确使用。资料公开方法使读者能够检查推理，同时保留平台后来更新的可能。',
      'Citizen Lab experiments found that some files exchanged among non-China-registered WeChat accounts helped populate censorship for China-registered users. Controlled comparisons supported inference.\n\nTime, accounts and content limit generalization. Surveillance, blocking and account punishment differ, and system evidence does not prove a human read every message.', ['wechat-research']),
    d('信息控制与公共危机', 'Information control during public crises',
      '疫情等危机中，谣言治理、风险沟通与政治审查可能重叠。删除明显虚假医疗信息有公共目的，限制真实求助和合理批评则会损害预警与信任。Citizen Lab对2020年初平台的样本测试记录疫情相关控制，具体规则与执行随时间调整。\n\n公众缺少可靠信息时更易传播未经核实消息，国家与平台应提供解释和纠错，而非只增加惩罚。被删内容需要独立核实，删除本身不证明其真实，也不证明其虚假。技术规则、人工执行与政治环境共同塑造信息的传播和删除。',
      'Crisis moderation can mix falsehood control with political censorship. Blocking genuine appeals can damage warning and trust. The 2020 tests had limited platform and temporal scope.\n\nDeletion proves neither truth nor falsehood. Technical rules, human moderation and political authority together shape information access and correction.', ['covid-censorship', 'who-timeline', 'wechat-research']),
    d('平台劳动与算法管理', 'Platform labor and algorithmic management',
      '派单、评分和路线系统提高匹配效率，也可能压缩劳动者可控制的时间和收入。司机、骑手、主播与创作者在合同、管理和收入来源上不同，平台对劳动的控制也各有方式。灵活性有真实价值，职业伤害、社会保险和申诉不足也有真实成本。\n\n算法不是脱离组织的自然力量，企业目标、数据选择和劳动规则决定其效果。算法考核影响工人的时间、安全与收入，拒绝危险任务和质疑错误的能力决定劳动者的实际处境。消费者追求即时服务的习惯也进入压力链，公共政策应使便利与保护相容，而不是要求劳动者自行承担全部风险。',
      'Dispatch and rating systems improved matching while restricting control over time and income. Platform occupations differ; flexibility and insecurity coexist.\n\nAlgorithms implement organizational choices. Understandable evaluation, refusal of unsafe tasks and appeals matter, as do consumer expectations and social insurance.', ['nbs-2025', 'reform-development', 'constitution']),
    d('生成式AI进入社会治理', 'Generative AI and social governance',
      '生成式人工智能扩大文本、图像和代码生产，为研究、教育和产业提供新工具。错误、偏见、隐私与责任问题又进入实际应用，能力评估、数据质量和纠错条件逐渐成为技术竞争与社会信任的交汇点。\n\n2023年生成式人工智能服务管理暂行办法规定服务责任、内容和数据等要求，法律目标与执行效果需要区别。安全保障、创新空间和表达限制可能发生张力，必须具体分析。本站历史正文与图表仍以可核查来源为基础，不把AI生成内容当作独立史料。',
      'Generative AI expanded production alongside hallucination, bias, privacy and accountability problems. Fluent output is not verification, and evaluation needs valid measures.\n\nThe 2023 interim rules establish service requirements, whose aims and outcomes differ. Safety, innovation and expression require specific analysis. AI output is not treated here as independent historical evidence.', ['ai-rules', 'constitution']),
  ],
  'hongkong-protests': [
    d('2014年雨伞运动与政改争议', 'The Umbrella Movement and electoral reform',
      '2014年围绕行政长官选举方案的争议引发占领和雨伞运动，参与者要求更具实质竞争的普选。中央强调提名与国家安全框架，香港不同社会群体对策略、秩序和未来有分歧。运动不是所有香港居民的一致选择，也不是仅由外部力量可以解释的现象。\n\n住房、机会与身份影响社会气氛，选举提名和问责等明确政治要求又使抗议超出经济问题。和平占领、个别暴力和政府执法在不同现场发生，居民经历组织、冲突与社会分裂。改革未获回应加深不信任，2019年的组织与诉求又在此前经验和新危机中发展。',
      'Disputes over the chief-executive election framework prompted the 2014 occupations. Participants sought meaningful electoral choice; central authorities emphasized nomination and security. Views within Hong Kong differed.\n\nEconomic pressures did not erase explicit political demands. Occupation, violence and policing require separate treatment, and 2014 and 2019 were distinct movements.', ['hongkong-declaration', 'hongkong-policy-2020']),
    d('2019年修例与诉求扩大', 'The 2019 bill and expanding demands',
      '2019年逃犯条例修订引发大规模反对，公众担心移交安排影响司法保障。政府先暂缓、后撤回法案，过程中诉求扩大到警务问责、被捕者、运动定性和选举。撤回法案以前的拖延与冲突侵蚀信任，诉求因此扩大到问责和政治制度。\n\n参与者包括和平游行者、较激进抗议者与不同职业群体，组织呈去中心化特点。参加者随着执法、冲突与政府回应改变要求，运动内部形成多种策略和立场。政府强调外部干预，许多居民则围绕制度与警务提出自身诉求，两种解释在社会中冲突。',
      'The extradition bill raised concerns about legal protection. Suspension and eventual withdrawal came amid widening demands over policing and representation. Timing and trust help explain continued protest.\n\nDecentralized participants and strategies varied. External pressure and local grievances intersected as protest developed.', ['hongkong-policy-2020', 'hongkong-declaration']),
    d('暴力、警务与一致标准', 'Violence, policing and consistent standards',
      '部分抗议者实施破坏、纵火和袭击，警察使用催泪弹及其他武力，严重伤害与争议事件需要逐件核查。记录抗议者暴力不使所有参加者成为罪犯，记录警务滥用也不表示任何抗议行为都正当。行为、指挥和调查责任应分开。\n\n国家掌握执法与拘禁权，警察对人群使用武力的方式和程序直接影响个人安全。独立调查、影像和现场证词成为社会追究具体责任的重要诉求。本书避免用最极端片段代表数月内全部公众行动。',
      'Some protesters used arson, attacks and destruction; police used tear gas and other force. Each incident needs verification. Neither side’s misconduct defines every participant.\n\nState power carries particular proportionality and procedural duties. Independent inquiry and contextualized evidence are preferable to treating extreme clips as the whole movement.', ['hongkong-policy-2020', 'hongkong-un-experts', 'constitution']),
    d('2020年国安法与制度转向', 'The 2020 National Security Law',
      '2020年香港国安法通过并实施，设立新的罪名、执法和司法安排。政府强调结束暴力、堵塞国家安全漏洞和恢复稳定，批评者及人权专家关注定义、程序和表达空间。两种论点需要与法律文本和具体案件比较，而不是只按立场选择。\n\n传媒、社团和政治组织空间随后改变，个人对言论与参与风险的判断也变化。抗议减少后，组织、媒体和表达空间仍明显收缩，秩序重建同时改变居民的参与条件。',
      'The 2020 law changed offenses, enforcement and courts. Government stabilization arguments and rights concerns require comparison with text and cases.\n\nMedia and civic space changed, affecting perceived participation risk. Reduced protest does not alone establish consent; order and restricted freedoms may coexist.', ['hongkong-policy-2020', 'hongkong-un-experts']),
    d('选举变化与2024年本地立法', 'Electoral changes and the 2024 ordinance',
      '后续选举制度调整强调爱国者治港，候选资格和代表结构变化，需要与回归初期及2010年代制度分别比较。2024年维护国家安全条例3月23日生效，落实基本法第二十三条本地立法，接续2020年国安法扩展治理。\n\n香港政府强调必要性和法律保障，联合国专家通信提出条款宽泛及权利影响关切。专家意见不是法院终审判决，政府保证也不是实际效果的独立证据。应持续观察案件、程序及新闻学术活动，而非在公布当天就预设所有未来结果。',
      'Electoral redesign changed eligibility and representation. The Safeguarding National Security Ordinance took effect on 23 March 2024 and is distinct from the 2020 law.\n\nGovernment assurances and UN expert concerns have different evidentiary status; neither settles every future case. Implementation requires continued observation.', ['hongkong-2024', 'hongkong-un-experts', 'hongkong-policy-2020']),
    d('迁移、信任与社会延续', 'Migration, trust and continuing society',
      '政治、疫情与经济共同改变移民决定，一些人明确因自由和制度忧虑离开，其他人则追求工作与家庭机会。留下者在责任、资源和认同中作出选择，也继续寻找适应和表达的方式。家庭跨境生活改变学校、照护和职业安排。\n\n香港仍有复杂经济和公共生活，政治变化不是全部城市史，却深刻影响参与与信任。未来增补需要纳入普通劳动者、移民和不同政治立场居民，以具体经验检验官方稳定叙述与社会损失论述。资料截止日前的事实和之后尚未完成的变化应保持分界。',
      'Politics, the pandemic and economic conditions shaped migration, with varied motives for leaving and remaining. Transnational families reorganized work and care.\n\nHong Kong’s economy and everyday life continued amid changed participation and trust. Later additions require varied residents’ experiences and clear cutoff boundaries.', ['hongkong-policy-2020', 'hongkong-2024', 'hongkong-un-experts']),
  ],
  'taiwan-strait': [
    d('2016年后的政治基础变化', 'Changing political foundations after 2016',
      '蔡英文2016年就任后，两岸对共同政治基础的认定出现更大分歧。大陆要求承认体现一个中国原则的基础，民进党政府强调台湾民主制度与维持现状，双方对既有表述的含义并不一致。交流机制受到影响，社会和商业联系却未立即消失。\n\n台湾内部对统独、身份和安全有多种观点，民进党、国民党及其他力量也随选举和形势调整立场。选民围绕经济、身份与两岸政策作出不同选择，投票结果带有多重诉求。大陆公众同样并非只有单一态度，但公开表达环境影响可见意见，比较民意需要注意方法与限制。',
      'After Tsai took office in 2016, disagreement over a shared political basis widened. Beijing emphasized one-China foundations; the DPP government emphasized democracy and the status quo. Social and business ties persisted despite disrupted mechanisms.\n\nElectoral choices do not identify every voter’s sovereignty preference. Public opinion on both sides requires attention to survey design and expression conditions.', ['taiwan-tsai', 'taiwan-republic', 'taiwan-whitepaper-2022']),
    d('2022年白皮书的大陆立场', 'The mainland position in the 2022 white paper',
      '大陆2022年白皮书重申台湾是中国一部分、实现统一及一国两制政策，同时表示不承诺放弃使用武力，称相关措施针对外部干涉和少数分裂势力。官方主张影响政策和军事信号，台湾居民则通过不同政党、选举和公共讨论表达自身选择。\n\n各方把历史、法律和民族叙事用于论证政策，外部干预、居民意愿、权利与战争后果相互纠缠。用武主张引发国际法、平民保护和地区安全争论，普通人的生活与自主参与始终处于风险之中。',
      'The 2022 white paper reaffirmed reunification and one country, two systems while declining to renounce force. Recording this position does not establish Taiwanese consent.\n\nHistorical and legal claims require separation from agreement. Any force option needs assessment of law, necessity, civilian protection and alternatives, beyond national objectives.', ['taiwan-whitepaper-2022', 'un-2758']),
    d('2024年选举与赖清德演说', 'The 2024 election and Lai’s address',
      '赖清德2024年当选并于5月就任，执政党与立法院力量分布不同，反映台湾选民在不同选票上的选择。就职演说表达维护民主、和平与既有政治体制的立场，大陆则对其两岸表述提出批评。演说是当事方立场证据，不是区域地位已经取得共同结论。\n\n外交政策与岛内治理相连，军费、能源、住房及议会监督都会影响公众判断。治理、经济和社会问题与统独争论交织，选举之后仍有具体的问责与公共服务任务。读者应能比较各方原文，而不是只接收摘要中的对抗性标签。',
      'Lai’s 2024 election and May inauguration occurred with a different legislative balance. His address stated democratic and peace positions, disputed by Beijing; it did not settle regional status.\n\nSecurity choices interact with budgets, energy and domestic accountability. Not every policy disagreement reduces to sovereignty, and electoral legitimacy does not end scrutiny.', ['taiwan-lai', 'taiwan-inauguration', 'taiwan-elections', 'taiwan-whitepaper-2022']),
    d('军演、灰色地带与误判', 'Exercises, gray-zone pressure and miscalculation',
      '军事演习、海空活动与对外安全合作改变风险感知，威慑、训练和政治信号可能同时存在。活动次数增加不必然表示战争已经决定，未发生战争也不说明风险虚假。具体事件需要标明地点、日期、规模和来源，避免把所有飞行都称作进入领空。\n\n领空、领海、防空识别区和海峡中线不是相同法律概念，示意图应明确类别。危机沟通、海空相遇规则和政治表态影响误判，居民与航运承担不确定性。武器、意图、预警、补给与升级风险共同影响海峡安全。',
      'Exercises and security cooperation combine deterrence, training and signaling. Activity does not prove a decision for war, while peace does not erase risk.\n\nAirspace, territorial waters, identification zones and the median line differ. Communication, encounter rules and leaders’ choices affect escalation as forces operate close to each other.', ['taiwan-whitepaper-2022', 'taiwan-inauguration', 'rapprochement-frus']),
    d('经济联系与社会选择', 'Economic connections and social choices',
      '贸易、投资、学生与家庭联系使两岸相互依赖，也可能形成不对称压力。经济交流延续家庭和商业联系，身份分歧与安全担忧仍持续发展。企业按市场和政策分散风险，劳动者与跨境家庭承担供应链调整的直接代价。\n\n半导体等产业增加台湾国际重要性，也可能加深安全竞争和供应链焦虑。技术优势不是保证和平的单一保险，产业迁移也并非必然导致某种政治结果。商业选择、国家管制和居民偏好相互影响，社会主体在对峙中继续维持生活联系。',
      'Trade and family links create interdependence and asymmetric pressure without automatically aligning identity. Firms diversify while workers and families absorb adjustment.\n\nSemiconductors increase strategic importance without guaranteeing peace or predetermining politics. Commercial, regulatory and social choices require separate analysis.', ['taiwan-republic', 'trade-review', 'chip-controls']),
    d('外交措辞与未来边界', 'Diplomatic wording and the future boundary',
      '不同国家的一个中国政策、中华人民共和国的一个中国原则及台湾政府主张并非完全相同，承认、认知与支持等措辞需要依据具体文件。联合国大会第2758号决议处理中国代表权，各方对于台湾地位及其国际参与继续持不同主张。解释这些差异，是准确叙述而非有意模糊立场。\n\n本书截至资料截止日不预判统一、独立或战争结局，也不将尚未发生的2026年后事件列入编年事实。以和平、居民权利和一致证据标准检验各方行为，允许读者看到真实分歧与可选择路径，避免将灾难写成不可避免的历史命运。',
      'National one-China policies, Beijing’s principle and Taiwan’s claims are not identical. Recognition language and UN representation require precise documents.\n\nNo future sovereignty or war outcome is presented as inevitable. The account applies peace, residents’ rights and consistent evidence through the cutoff date.', ['un-2758', 'rapprochement-frus', 'taiwan-inauguration', 'taiwan-whitepaper-2022']),
  ],
  'trade-tech-conflict': [
    d('从经贸争议到2018年关税', 'From trade disputes to the 2018 tariffs',
      '中美在市场准入、补贴、知识产权和技术转让上的分歧长期存在，2018年美国依据国内301调查实施关税，中国采取反制。美方以自身法律和战略说明措施，中方强调公平与发展，具体关税和限制又进入国际规则争议。\n\n关税先由进口商缴纳，其成本又经价格、利润与订单分散到消费者、企业和工人。第三国可能获得订单，也面临规则变化。将争端写成两国领导人个人争吵，会遗漏国内产业、选民与跨国企业的利益，以及全球生产网络已形成的相互依赖。',
      'Longstanding disputes led to US Section 301 tariffs in 2018 and Chinese retaliation. US domestic investigations, WTO procedures and Chinese responses developed through distinct legal and political channels.\n\nLegal tariff payment and ultimate economic incidence differ. Consumers, firms, workers and third countries experienced uneven effects, beyond leaders’ personal conflict.', ['trade-301', 'trade-review', 'wto-accession']),
    d('谈判、采购承诺与持续关税', 'Negotiation, purchase commitments and persistent tariffs',
      '后续谈判形成阶段性协议和采购安排，缓和部分争议，却没有取消所有关税和结构问题。协议承诺、实际采购与疫情冲击交错，沟通延续的同时贸易摩擦仍在发展。\n\n政策清单不断调整，豁免和产品分类使企业成本差异显著。历年税率和适用条件变化，企业随当时规则调整订单、价格和供应。政府公开解释提供立场证据，真实经济效果仍需价格、贸易转移、就业和企业数据共同检验。',
      'Partial agreements and purchase commitments did not eliminate all tariffs. Promises, realization and pandemic shocks require separation.\n\nExclusions and classifications changed firm costs over time. Prices, employment and trade reveal how contemporary rules affected businesses and households.', ['trade-301', 'trade-review']),
    d('2022年半导体出口管制', 'The 2022 semiconductor controls',
      '美国2022年10月加强先进计算和半导体制造相关出口管制，强调国家安全及军事用途风险。规则分别限制特定产品、设备、最终用途与人员活动，先进制造和科研合作因此受到不同影响。后续版本另有变化，本书引用2022年文件时不声称它涵盖2026年全部现行规则。\n\n中国强调技术自主和产业链安全，企业寻找替代、储备与研发。管制可能延缓某些能力，也激励替代和增加成本，最终效果取决于技术、盟友执行和创新。限制改变技术取得与成本，企业攻关取得部分突破，设备、软件和供应网络的依赖仍各不相同。',
      'October 2022 controls targeted advanced computing and manufacturing through varied product, end-use and activity rules, not a ban on every chip. Later versions require separate verification.\n\nChina pursued substitution and autonomy. Delay, innovation and added costs can coexist; neither a restriction nor a breakthrough settles all dependencies.', ['chip-controls', 'trade-review']),
    d('企业调整与供应链重组', 'Firm adaptation and supply-chain restructuring',
      '企业通过迁移部分生产、增加库存、改变供应商或设置区域体系分散风险，贸易流向变化不一定表示全部产能离开中国。最终组装转移与零部件、设备和管理仍来自原网络，可以同时发生。海关原产地与完整增加值来源也不相同。\n\n新工厂创造当地就业，原产地的工人和供应商则承受订单与技能调整。企业也需兼顾市场、能源、物流和人才，政治风险是多种因素之一。所谓脱钩、去风险与产业升级应给出明确指标，避免用流行词概括所有复杂变化。',
      'Relocation, inventory and supplier diversification did not necessarily remove entire production networks. Customs origin differs from value-added sources.\n\nNew and old workers faced uneven adjustment. Market, energy and skills complemented political risk. Tariffs, investment restrictions and supply-chain changes gave concrete form to economic separation.', ['trade-review', 'reform-development', 'wb-2026']),
    d('安全、科研与开放的张力', 'Security, research and openness',
      '技术具有民用与军用交叉，国家对高风险用途可提出限制，但过宽管制也可能损害基础科研、人员交流和商业竞争。军民两用风险审查同国籍和族裔偏见的争论交织，科研人员面临合作、流动与身份压力。\n\n出口规则、投资审查与大学合作限制通过各自法律渠道实施。科研生态依赖国际知识流动，同时需要透明利益、数据保护和可追责合作。安全限制改变技术取得和合作，也给合法科研、企业与个人带来误伤风险。',
      'Dual-use risks can warrant controls, while overbreadth harms research and exchange. Nationality is not evidence of individual threat, and not every restriction is merely protectionism.\n\nExport law, investment screening and university rules differ. Evaluation requires both risk reduction and collateral harm, with accountable cooperation.', ['chip-controls', 'trade-review', 'ai-rules']),
    d('2026年的观察与未完成结果', 'Observations and unfinished outcomes in 2026',
      '截至资料截止日，关税与技术政策仍在演变，预测产业赢家或长期增长损失具有高度不确定性。本书保留已核查政策的年份，不编造全年贸易结果，也不由某个企业发布会推定国家整体技术地位已经逆转。\n\n评估长期影响需要生产率、消费价格、创新和安全等不同指标，利益也跨越国家边界。世界银行2026年更新提供宏观背景，预测并不是结算结果。未来增补将按具体新规则和实施证据更新，保留旧版本的历史环境，而不是用现行政策覆盖全部过去。',
      'Policies and outcomes remain evolving. Verified years are preserved, without invented full-year results or national conclusions from individual announcements.\n\nProductivity, prices, innovation and security differ. World Bank forecasts described expected conditions at publication; actual developments continued changing the outlook.', ['trade-301', 'chip-controls', 'trade-review', 'wb-2026']),
  ],
  'covid-19': [
    d('2019年底预警与早期信息', 'Warnings and early information in late 2019',
      '2019年底武汉出现不明原因肺炎，医务人员、医院和公共机构逐步发现异常。早期病原和传播方式尚未完全明确，医生提醒、正式报告、公开通报与执法处理却有不同责任。对李文亮等人的训诫压缩了专业警示空间，公众后来对信息透明与问责提出强烈要求。\n\n科学不确定性要求及时共享并修正信息，而不是保证最初判断永远不变。地方、中央和国际机构掌握情况有时间差，病毒溯源又是与早期应对责任相关但不同的问题。本书不把未经证实的起源假说写成事实，也不让溯源争论遮蔽可以调查的报告与决策过程。',
      'Wuhan’s unexplained pneumonia emerged in late 2019 amid incomplete knowledge. Clinical warnings, formal reporting, public disclosure and police action involved distinct duties; reprimanding reasonable warnings was not justified by scientific uncertainty.\n\nResearchers and clinicians exchanged evidence as understanding of the disease changed. Origin hypotheses and response accountability are related but separate, and unproven origins do not replace investigation of decisions.', ['who-timeline', 'covid-censorship']),
    d('2020年武汉封控与全国应对', 'Wuhan restrictions and the 2020 response',
      '2020年1月武汉交通封控后，全国通过病例隔离、接触追踪、社区管理和医疗扩容控制传播。医护、建设人员、志愿者与居民承担重大劳动，物资和医院压力在早期尤其严重。较早控制为部分地区争取准备时间，执行中的就医延误和生计损失又引发争议。\n\n急救、慢性病、孕产和基本生活在限制中受到冲击，求助者处境与政策平均效果需要同时记录。社区互助和资源差异使居民经历不同。不同阶段的感染风险、医疗能力与措施强度变化，使疫情防控与非疫情伤害形成不同组合。',
      'After Wuhan’s January restrictions, isolation, tracing, community controls and expanded care reduced transmission. Workers and residents carried substantial burdens.\n\nEmergency, chronic and maternity care also suffered. Mutual aid and resources shaped unequal experiences. Phase-specific benefits and indirect harm need joint assessment.', ['who-timeline', 'who-china-2023', 'covid-censorship']),
    d('动态清零的收益与条件变化', 'Dynamic zero COVID and changing conditions',
      '较长时间压低传播减少早期感染和死亡，为疫苗与医疗准备提供窗口。随着病毒变异、传播力增强及其他国家政策转变，原有措施的成本和可持续性变化。疫苗、病毒和医疗条件变化以后，延续高强度限制带来日益扩大的成本。\n\n老年人疫苗覆盖、重症资源与基层服务决定退出风险，政策目标应与真实准备相连。检测与隔离规模扩大形成财政和执行激励，层层加码及不透明规则又削弱信任。保护生命的目标需要包含感染死亡，也包括延误医疗、心理与生计损害。',
      'Suppressed transmission reduced early harm and created preparation time. More transmissible variants changed cost and sustainability; neither retrospective rejection nor indefinite continuation follows automatically.\n\nOlder-adult vaccination and care capacity shaped exit risk. Testing incentives and overimplementation affected trust. Protection includes indirect health and livelihood harms.', ['who-timeline', 'who-china-2023', 'covid-excess-2023']),
    d('2022年封控中的生活冲突', 'Everyday conflicts during 2022 restrictions',
      '上海等地2022年长时间限制使食品、急诊、隔离安排和家庭分离成为公共争议。居民对感染风险与措施的态度不同，既有人担心放开，也有人难以承受继续限制。以统一标签称赞或责备所有居民，无法解释不同身体和经济条件。\n\n基层干部、配送员和志愿者在压力下执行政策，有真实付出，也有侵权和资源失配。规则、考核和指挥沿行政链条传递压力，最终执行者与上层决定共同影响居民受到的待遇。公开投诉和真实信息本可帮助纠错，限制其传播会增加政策失明。',
      'Long 2022 restrictions raised disputes over food, emergency care, isolation and separation. Residents differed in infection risk and ability to bear controls.\n\nFrontline effort coexisted with abuse and misallocation. Rules and command chains matter alongside individual conduct; suppressing feedback can obstruct correction.', ['who-china-2023', 'covid-excess-2023', 'constitution']),
    d('白纸抗议与公共表达', 'White Paper protests and expression',
      '2022年11月乌鲁木齐火灾后，多地出现悼念和抗议，白纸成为表达审查与不满的象征。参与者诉求包括结束过度限制、获得表达空间及更广政治要求，并非所有人持有相同纲领。火灾具体救援责任与全国抗议缘由需要分别核查，不把未经充分证实的现场说法当定论。\n\n国际特赦组织后来访谈六名参与者，记录拘押、压力和创伤经历，这是明确归属的证言，不是全国随机样本或拘捕总数。和平表达应受到保护，个案仍需核查。抗议、经济压力、疫情形势与内部政策调整相互交错，限制很快被撤除。',
      'After the November Urumqi fire, mourning and protests used blank paper to symbolize censorship and varied demands. Specific fire-response claims require their own verification.\n\nAmnesty’s six interviews provide attributed experiences, not representative totals. Peaceful expression merits protection. Temporal proximity to policy change alone does not establish one cause.', ['white-paper-testimony', 'constitution']),
    d('2022年底政策退出与感染潮', 'The late-2022 exit and infection wave',
      '2022年底防控快速放宽，感染和就医需求骤增，药品、医院和殡葬服务承受压力。退出本身回应旧措施不可持续的问题，退出速度、沟通与准备是否充分则属于不同评价。分阶段准备、疫苗和可靠救治本可减轻转向风险，突然退出则把感染和生活恢复压缩到很短时间。\n\n高龄、有基础病和服务不足地区居民风险更大，家庭照护承担大量工作。官方医院死亡通报与社会全部死亡不是同一范围，世界卫生组织要求更详细数据。检测缩减改变病例通报，传播、就医和死亡记录在政策转向后出现新的统计条件。',
      'Rapid relaxation brought surging infections and care demand. The need to end unsustainable controls differs from whether timing and preparation were adequate. Alternatives were not limited to sudden exit or endless lockdown.\n\nOlder people and poorly served regions faced greater risk. Hospital deaths and population mortality differ, while reduced testing changes case counts.', ['who-china-2023', 'covid-excess-2023']),
    d('超额死亡研究与测量限制', 'Excess-mortality research and measurement limits',
      '超额死亡测量全因死亡相对正常基准的增加，感染、医疗延误等途径共同造成生命损失。2023年JAMA研究利用三所大学讣告与搜索数据外推全国变化，提示退出后死亡显著增加，同时受代表性、搜索行为和基准假设限制。\n\n模型以全因死亡估计超额死亡并给出区间，研究结果随资料与方法不同而变化。官方通报记录特定机构和时段的死亡，人口研究采用更广范围；两类资料分别揭示疫情后果与统计中的缺口。',
      'Excess mortality includes multiple pathways beyond confirmed infection. A 2023 JAMA study extrapolated university obituaries and search data, finding a substantial increase with important representativeness and baseline limits.\n\nModels are not registers, and restricted official reports are not population upper bounds. Each measure identifies a different population, period and form of loss.', ['covid-excess-2023', 'who-china-2023']),
    d('疫情后遗产与责任记录', 'Post-pandemic legacies and accountability',
      '复工和出行恢复不使丧亲、长期健康、失学和债务问题立即消失。医护劳动、家庭互助与志愿行动应被记住，失误、隐瞒和不必要强制也需进入记录。感染、照护与风险选择使家庭面对压力，污名又加重病人与亲属的负担。\n\n持续公共卫生准备需要疫苗、监测、基层医疗、可信信息和社会保障。历史教训不是选择最严或最松的固定口号，而是依据证据调整、保护弱者与保留纠错。本书以资料截止日前可核查记录为准，尚缺的完整死亡、长期影响与内部决策资料公开列为后续研究问题。',
      'Reopening did not erase bereavement, lasting illness, disrupted learning or debt. Recognition of care and mutual aid belongs beside investigation of concealment and unnecessary coercion.\n\nPreparation requires monitoring, credible information and social protection. Missing mortality and decision records continue limiting reconstruction of the crisis.', ['who-timeline', 'who-china-2023', 'covid-excess-2023']),
  ],
  'climate-transition': [
    d('污染治理与气候政策的区别', 'Pollution control and climate policy',
      '空气、水和土壤污染直接影响健康，温室气体则通过全球气候机制产生长期风险，两者有关却不同。减少煤炭燃烧可能同时降低颗粒物和碳排放，某些末端治污技术却主要处理局部污染。空气污染治理改善部分健康环境，温室气体排放又受到能源总量和经济结构影响。\n\n环境治理经历从工业扩张、地方保护到更集中监管的变化，居民投诉、媒体、科研和政策共同推动。执法改善可产生实际收益，突击停产和不透明检查又可能损害企业与工人。持续排放、居民健康和执行公平决定环境治理的长期影响。',
      'Local pollution and greenhouse gases differ, despite shared sources. Air-quality improvements accompanied continuing carbon pressures from energy and industrial production.\n\nResidents, research and regulation shaped change. Enforcement benefits coexist with risks from abrupt controls; durable emissions and fair implementation matter.', ['climate-ndc', 'nbs-2025']),
    d('2030与2060目标的含义', 'The 2030 and 2060 targets',
      '中国提出2030年前碳达峰、2060年前碳中和，并通过国家自主贡献文件说明目标和措施。达峰意味着排放由升转降，中和则追求排放与吸收平衡，两项目标要求不同阶段持续改变生产与能源。\n\n目标文本是国际承诺和政策方向，不是已经实现的数据。比较排放总量、人均、单位GDP及消费责任会得到不同视角，需要标明范围。历史工业化与当代生产都形成责任，发展需求和减排任务在国际谈判中共同塑造政策。',
      'Peaking before 2030 and neutrality before 2060 are distinct commitments, not completed results. Total, per-capita, intensity and consumption-based emissions use different perspectives.\n\nHistorical and present responsibilities coexist. Development needs do not remove every mitigation duty.', ['climate-ndc']),
    d('新能源扩张与电网约束', 'Renewables and grid constraints',
      '风电、光伏、电动车和储能发展改变制造业与能源结构，规模扩大推动成本下降和技术进步。装机提供能力，天气、电网和储能决定发电及实际送达，新能源扩展需要配套系统。电网、调峰、储能和跨区域输电决定可再生能源利用。\n\n煤电承担供电和调节，清洁能源在增长的需求中扩张。价格、安全和排放目标相互牵制，地方投资又可能重复建设；装机、实际发电与能源消费分别显示这场转型的不同进程。',
      'Wind, solar, vehicles and storage expanded capabilities, but installed capacity differs from delivered electricity. Grids and flexibility determine utilization.\n\nCoal and clean additions can coexist. Prices, security and emissions shape energy use, while generation, grid access and demand determine the effect of added capacity.', ['nbs-2025', 'climate-ndc']),
    d('煤炭地区与公正转型', 'Coal regions and a fair transition',
      '减煤和产业调整影响矿工、地方财政和依赖单一产业的城市，新增绿色岗位未必在同一地点或适合原技能。新能源创造岗位，传统行业的工人仍要经历培训、迁移与收入中断，转型收益和损失分布不均。培训、养老金、迁移和公共服务决定转型能否公平。\n\n新能源生产也需要矿产、土地、水和设备处理，绿色标签不使供应链自动没有环境问题。居民参与、劳动安全与回收制度应伴随扩张。2026年世界银行更新将绿色技能与社会保障列为转型条件，强调就业和照护政策配套。',
      'Coal adjustment affects workers and local budgets, while green jobs may differ in location and skills. Aggregate job gains do not compensate each displaced worker.\n\nClean technology also requires minerals and land. The 2026 World Bank analysis identifies green skills and social protection as continuing needs of the transition.', ['wb-2026', 'climate-ndc', 'nbs-2025']),
    d('国际贸易与绿色产业竞争', 'Trade and competition in green industry',
      '中国新能源制造降低部分全球转型成本，也引发补贴、产能与市场竞争争议。贸易伙伴对电动车、光伏等采取措施，国家安全、产业保护和气候目标可能互相冲突。应具体说明法律和产品，不把任何绿色产品关税都视作同一理由。\n\n低价格可能来自规模、技术、投入和政策，多种因素需要实证分辨。国内外消费者、工人和财政承担不同成本，全球减排又需要合作。产业竞争影响排放、就业与技术扩散，工人和地区社区承受转型中的具体变化。',
      'Chinese manufacturing reduced some transition costs while provoking subsidy and capacity disputes. Trade, industry and climate priorities can conflict.\n\nPrices reflect multiple causes. Consumer, worker and fiscal effects coexist with global mitigation needs, requiring more than a national winner–loser frame.', ['trade-review', 'climate-ndc', 'wb-2026']),
    d('核查目标与实测的时间差', 'The time gap between pledges and observations',
      '能源数据和国际清单按不同边界及版本发布，年度修订反映统计资料的持续更新。碳市场、地方计划和产业投资需要后续排放核查，交易量也不直接等于净减排。政策有效性依赖基准、额外性与执行。\n\n2026年仍未结束，本书不声称掌握全年最终排放。未来更新将保留数据发布日、测量单位和预测标签，用实际趋势检验承诺。图表的作用是帮助理解制度和数据，不是用未来目标填补尚不存在的观测值。',
      'Energy data and emissions inventories use differing boundaries and revisions. Trading volume does not equal additional mitigation; baselines and enforcement matter.\n\nNo final 2026 emissions are claimed. New statistics and events enter later editions with their release dates and definitions.', ['climate-ndc', 'nbs-2025']),
  ],
  'demographic-turn': [
    d('2025年数据的准确范围', 'The precise scope of the 2025 data',
      '国家统计局2025年统计公报报告出生792万人、死亡1131万人，年末人口140489万人，比上年减少339万人。公报于2026年发布，数字描述2025年而非2026年。人口统计覆盖大陆31个省区市及现役军人，港澳台居民与外籍人员等另用各自口径统计。\n\n出生减死亡得到自然减少，年末人口变化还需注意统计与调整口径。将人口总量、自然增长率和年龄结构同时观察，才能理解趋势。人口变化在地区间不同，长期年龄结构与当下选择共同作用于每年的出生和死亡。',
      'The 2025 communiqué reported 7.92 million births, 11.31 million deaths and 1,404.89 million year-end population, down 3.39 million. Released in 2026, the figures cover the 2025 mainland population including military personnel, under the NBS definition.\n\nTotals, natural change and age structure differ. One year does not establish uniform regional trends or a short-term policy’s causal effect.', ['nbs-2025']),
    d('低生育的多重原因', 'Multiple causes of low fertility',
      '生育选择受育龄人口、婚姻、教育、住房、工作和照护共同影响，过去政策又改变家庭结构与预期。年轻人的选择受到就业、住房和养育条件制约，数量限制结束后，这些压力仍持续影响出生。女性机会扩展是社会进步，家庭支持不足则使生育与职业形成不必要冲突。\n\n生育意愿、结婚与实际出生各有变化，经济条件和家庭计划影响最终选择。经济不确定、就业歧视和祖辈照护资源使家庭差异显著。可负担托育、父母共同休假和稳定保障影响家庭能否实现自己的生育计划。',
      'Cohorts, marriage, education, housing, employment and care interact with earlier policy. Housing, work, care and family expectations shaped low fertility after restrictions eased.\n\nIntentions and births differ. Childcare, shared leave and secure work address constraints without treating women’s bodies as targets.', ['birth-policy', 'birth-policy-study', 'unfpa-programme']),
    d('老年人的劳动、照护与公共生活', 'Aging without treating older people as a burden',
      '寿命延长是重要成就，老龄化同时改变养老、医疗和劳动安排。健康老人继续工作、照顾家庭与参与公共生活，代际支持在老龄社会中持续变化。高龄、失能与低收入群体需要更多支持，不同地区和社会群体的健康年限存在差异。\n\n养老金、长期护理和社区服务的城乡差异影响家庭责任，女性常承担更多无偿照护。家庭养老与社会服务不是非此即彼，适当公共支持可以减少亲属耗竭。讨论财政可持续时也应承认老人一生贡献和权利，不把代际关系写成争夺资源的简单战争。',
      'Longer lives are an achievement, while care and labor needs change. Older people vary in health and contribution; age alone does not define dependence.\n\nUnequal pensions and services place care burdens, often on women. Public support can complement families, with dignity and contribution recognized alongside fiscal sustainability.', ['unfpa-programme', 'nbs-2025', 'poverty-report']),
    d('劳动人口与生产率', 'Workforce size and productivity',
      '劳动年龄人口变化会影响供给，却不机械决定经济增长。教育、技术、健康、劳动参与和资源配置可以改变每名劳动者产出，自动化也可能补充某些岗位而替代另一些岗位。人口收缩带来劳动、养老与地方服务压力，生产率、迁移和公共政策影响其具体后果。\n\n退休、职业培训与跨地区流动政策需要考虑工种和健康，办公室与重体力劳动者并不具有相同延长工作的能力。青年就业不足和企业招工困难也可能并存，表明技能与地区匹配重要。人口史应连接制度和劳动，而不是只用一条总人口曲线解释全部经济。',
      'Workforce decline affects supply without mechanically determining growth. Skills, health, participation and technology alter productivity, with uneven automation effects.\n\nRetirement and retraining policies affect people differently across occupations and health conditions. Skill and regional mismatch can create labor shortages alongside youth unemployment, complicating demographic pressures.', ['nbs-2025', 'wb-2026', 'unfpa-programme']),
    d('地区收缩与人口流动', 'Regional shrinkage and mobility',
      '全国人口转折伴随城市和地区重新分布，一些都市圈吸引人口，部分县域与老工业地区持续流出。学校、医院和住房随人口重新布局，小城镇与乡村的服务可达性成为新问题。留守老人、儿童和交通不便家庭可能因此承担更高成本。\n\n户籍、财政与常住人口之间的衔接决定流动者能否取得权利，人口迁入也需要住房和基础设施。空置住房总量并不表示每位城市居民买得起房，地域和品质不同。比较人口与房地产应使用对应地区，避免全国总量掩盖城市之间完全不同的情况。',
      'National decline coexists with concentration in some metropolitan areas and outflow elsewhere. Service consolidation can raise costs for residents with limited mobility.\n\nResidence-based rights and finance matter for migrants. Vacant housing does not guarantee affordability where demand exists; geography and quality require matching.', ['nbs-2025', 'wb-2026', 'hukou-1958']),
    d('尊重选择的长期社会政策', 'Long-term policy that respects choice',
      '人口政策需要从单一数量管理转向人的健康、教育、照护与自主选择。希望生育和选择少生的居民都在安排自身生活，托育与服务支持扩大可行选择。移民、延长健康工作与提高生产率也属于讨论，但各有制度和权利条件。\n\n长期变化不可能由一次补贴立刻逆转，评估应预先明确目标和时间，保留未达预期的结果。2026年最终人口数据尚未公布，本书以2025年公报为最新完整年度基础。未来更新将记录修订和新证据，避免把政策愿望提前写成社会事实。',
      'Policy can support desired births while respecting those who do not have children. Health, education and care matter beyond targets, with other options subject to rights and institutions.\n\nPopulation aging and smaller birth cohorts continued after the policy change. The latest complete annual basis here is 2025; final 2026 population is not invented.', ['unfpa-programme', 'nbs-2025', 'wb-2026']),
  ],
  'china-2026': [
    d('当代史的开放结尾', 'An open ending for contemporary history',
      '1840—2026年的长期转型仍在延续，当前经济、社会和国际关系继续变化。本书资料截止日为2026年10月10日，修订于10月11日，之后事件不在本次编年事实范围。新资料和修订统计不断扩展对过去的认识，各版记录相应更新。\n\n2026年的已公布季度资料、2025年完整年度数据和对2027年的预测具有不同地位。页面显示的日期不是信息自动实时更新的保证，读者应能核查每项来源。本章连接长期机制与当前约束，避免将当下感受扩写成对未来必然性的判断。',
      'The account ends openly, with evidence through 10 October 2026 and revision on 11 October. Later events and retrospective revisions require new versions.\n\nComplete 2025 statistics released in 2026 record industrial capacity, population decline and changing employment. Quarterly observations and institutional forecasts show a growth model under pressure from property adjustment and weak household demand.', ['wb-2026', 'nbs-2025']),
    d('房地产调整与家庭资产', 'Property adjustment and household assets',
      '房地产调整牵动开发商、购房家庭、建筑就业和地方财政，住房交付、债务与价格变化影响信心。多套房业主、刚购房者与租房家庭承受不同价格和债务变化，平均房价背后存在明显分化。地方土地收入下降又可能传到公共服务和偿债。\n\n保交付、企业融资和市场稳定措施以不同方式分配风险，家庭、开发商和金融机构承受不同后果。支持政策帮助完成部分项目，原有投资失误与损失分担仍影响长期财政和居民生活。长期问题涉及住房需求、人口和财政结构，历史上形成的增长模式需要逐步重组。',
      'Property adjustment affects developers, buyers, construction and local finance unevenly. Average prices do not identify every household’s gain or loss.\n\nCompletion support, firm rescue and loss redistribution are distinct. Housing demand, demography and fiscal structure combined to shape the adjustment.', ['wb-2026', 'stimulus-study', 'housing-1998']),
    d('消费、储蓄与社会保障', 'Consumption, saving and social protection',
      '收入预期、住房、医疗、养老和教育负担推动预防性储蓄，弱化居民消费。扩大保障可能提高消费信心，收入分配和就业同样重要。投资、出口与价格共同改变消费占比，家庭支出又受就业与保障影响。\n\n非正规就业与流动人口若无法同等获得服务，会在城市贡献与家庭风险之间形成缺口。2026年世界银行更新强调更强社会安全网及按居住提供服务的条件，这是政策分析而非所有问题已经解决。公共支出方向和可持续财政需要一起考虑。',
      'Cautious consumption reflects income, housing and service risks, not merely unwillingness. Distribution and employment matter alongside protection.\n\nInformal workers and migrants face gaps. The 2026 World Bank update discusses stronger residence-based services as a condition, not an accomplished outcome.', ['wb-2026', 'poverty-report', 'nbs-2025']),
    d('创新投资与经济结构', 'Innovation investment and economic structure',
      '高技术制造和人工智能投资带来新能力，也需区分投入、产品应用与实际生产率。专利、论文或模型参数不直接代表社会收益，重复投资和评估失真可能消耗资源。科研自主与国际交流在安全和发展目标之间相互牵动，也通过知识和产业合作提供支持。\n\n企业、大学、研究者和用户分别承担风险与贡献，产业政策需要真实反馈。新技术吸引投资与政策支持，安全、信任和商业可行性影响其实际应用。科研失败、日常试验和普通劳动同重大成果一起构成技术发展的过程。',
      'High-tech and AI investment create capacity, but inputs and patents do not establish productivity or social value. Evaluation and duplication risks remain.\n\nFirms, researchers and users contribute differently. Forecast support from innovation does not guarantee future success; safety, trust and records of failure matter.', ['wb-2026', 'ai-rules', 'nbs-2025']),
    d('全球环境与政策预测', 'Global conditions and policy forecasts',
      '世界银行2026年7月更新预计当年增长4.4%、2027年4.3%，这些是该时点预测，不是已经实现的年度增长率。房地产、消费、能源与外部需求变化，使各机构不断调整经济预测。不同机构模型与发布日期也需保留。\n\n贸易、技术和气候政策跨国互动，国内发展始终处于国际环境之中。国家竞争叙述容易忽略跨境家庭、工人和消费者共同承受的成本。合作与冲突改变企业、政府和居民的选择，政策后果在实际贸易、投资与生活中逐步显现。',
      'The World Bank’s July 2026 forecasts of 4.4% for 2026 and 4.3% for 2027 are dated expectations, not realized annual growth. Subsequent conditions may differ.\n\nTrade, technology and climate interact internationally. Cross-border household and worker costs complement national narratives, with policies tested against evidence.', ['wb-2026', 'trade-review', 'climate-ndc']),
    d('公开范围与后续史料工作', 'Public scope and future evidence work',
      '本书以明确编年总目覆盖各阶段及政治、战争、经济、社会、文化、环境和国际关系，并提供人物行动与专题长章。它不是宣称穷尽每个县、每个家庭与每一天，而是让已经纳入和仍待增补的范围可核查。\n\n后续工作包括更细地方史、家庭经验、原始档案校勘及新发布统计，重大争议保留不同证据的可追踪出处。新增内容同样遵循中英对应、来源说明和不确定性标记。开放结尾让读者看到研究过程，也避免把2026年临时判断封成永远不变的终章。',
      'The explicit chronology covers phases and major themes, with biographies, actions and studies. It does not claim every county or day; included and future scope remain auditable.\n\nLocal archives and oral histories provide further evidence of households, workers and communities. Future bilingual additions retain sources, limitations and versioned statistics.', ['nbs-2025', 'wb-2026', 'political-campaign-databases']),
  ],
};
